import React, { useState } from "react";
import { Dashboard } from "./components/Dashboard";
import { Sidebar } from "./components/Sidebar";
import { Header } from "./components/Header";
import { ClientsView } from "./components/ClientsView";
import { TasksView } from "./components/TasksView";
import { WorkerMetrics } from "./components/WorkerMetrics";
import { Settings } from "./components/Settings";
import { StatusProvider, useStatus } from "./contexts/StatusContext";
import { SettingsProvider } from "./contexts/SettingsContext";

const AppContent: React.FC = () => {
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [currentView, setCurrentView] = useState("dashboard");
  const { state } = useStatus();

  return (
    <div className="min-h-screen bg-gradient-to-br from-secondary-50 to-secondary-100">
      {/* Sidebar */}
      <Sidebar
        isOpen={sidebarOpen}
        onToggle={() => setSidebarOpen(!sidebarOpen)}
        currentView={currentView}
        onViewChange={setCurrentView}
      />

      {/* Main Content */}
      <div
        className={`transition-all duration-300 ${sidebarOpen ? "lg:ml-64" : "lg:ml-16"}`}
      >
        {/* Header */}
        <Header
          onSidebarToggle={() => setSidebarOpen(!sidebarOpen)}
          sidebarOpen={sidebarOpen}
        />

        {/* Main Dashboard */}
        <main className="p-4 lg:p-6">
          <div className="max-w-7xl mx-auto">
            {currentView === "dashboard" && <Dashboard />}
            {currentView === "clients" && <ClientsView />}
            {currentView === "tasks" && <TasksView />}
            {currentView === "metrics" && <WorkerMetrics clients={state.clients} />}
            {currentView === "settings" && <Settings />}
          </div>
        </main>
      </div>

      {/* Mobile sidebar overlay */}
      {sidebarOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden"
          onClick={() => setSidebarOpen(false)}
        />
      )}
    </div>
  );
};

function App() {
  return (
    <SettingsProvider>
      <StatusProvider>
        <AppContent />
      </StatusProvider>
    </SettingsProvider>
  );
}

export default App;
